// UNIFIED SERVICE WORKER (PWA + FIREBASE)
// This file handles both PWA caching and Firebase Background Notifications.

// 1. Load PWA caching logic (generated by next-pwa)
importScripts('/sw.js');

// 2. Load Firebase Scripts
importScripts('https://www.gstatic.com/firebasejs/9.0.0/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/9.0.0/firebase-messaging-compat.js');

// 3. Initialize Firebase in Service Worker
// IMPORTANT: Replace these placeholders with your actual keys from Firebase Console
firebase.initializeApp({
  apiKey: "YOUR_API_KEY",
  authDomain: "YOUR_PROJECT_ID.firebaseapp.com",
  projectId: "YOUR_PROJECT_ID",
  storageBucket: "YOUR_PROJECT_ID.appspot.com",
  messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
  appId: "YOUR_APP_ID"
});

const messaging = firebase.messaging();

// 4. Handle Background Messages
messaging.onBackgroundMessage((payload) => {
  console.log('FCM SW: Received background message ', payload);

  const notificationTitle = payload.data.title || payload.notification.title || 'StudyScript Update';
  const notificationOptions = {
    body: payload.data.body || payload.notification.body || 'You have a new message',
    icon: payload.data.icon || '/icons/icon-192x192.png',
    data: {
        link: payload.data.link || '/'
    }
  };

  self.registration.showNotification(notificationTitle, notificationOptions);
});

// 5. Handle Notification Click
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const targetLink = event.notification.data.link || '/';
  
  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      if (clientList.length > 0) {
        let client = clientList[0];
        for (let i = 0; i < clientList.length; i++) {
          if (clientList[i].focused) {
            client = clientList[i];
            break;
          }
        }
        return client.navigate(targetLink).then(c => c.focus());
      }
      return clients.openWindow(targetLink);
    })
  );
});
